// Pick the newest UFC stories that this workflow has not posted or skipped yet.
const settings = $('Settings').first().json;
const feeds = $('News sources').all().map((item) => item.json);
const memory = $getWorkflowStaticData('global');
const seen = new Set([...(memory.postedKeys ?? []), ...(memory.skippedKeys ?? [])]);

const maxAgeMs = Number(settings.maxStoryAgeHours || 48) * 60 * 60 * 1000;
// Extra candidates, because some stories have no usable image.
const candidateCount = Math.max(12, (Number(settings.exportsPerRun) || 5) * 5);

// The Code node sandbox has no URL class, so read the host and path with a pattern.
const urlParts = (url) => {
	const match = String(url ?? '')
		.trim()
		.match(/^https?:\/\/([^/?#]+)([^?#]*)/i);
	if (!match) return null;
	return {
		host: match[1]
			.replace(/^[^@]*@/, '')
			.replace(/:\d+$/, '')
			.replace(/^www\./i, '')
			.toLowerCase(),
		path: match[2],
	};
};

const host = (url) => urlParts(url)?.host ?? '';

const linkKey = (url) => {
	const parts = urlParts(url);
	if (!parts) return `link:${String(url).toLowerCase()}`;
	return `link:${parts.host}${parts.path.replace(/\/+$/, '')}`.toLowerCase();
};

const titleKey = (title) =>
	`title:${String(title)
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, ' ')
		.trim()}`;

const firstUrl = (value) => {
	if (!value) return '';
	if (typeof value === 'string') return value;
	if (Array.isArray(value)) return firstUrl(value[0]);
	return value.url || value.$?.url || value.href || '';
};

const looksLikeImage = (url) => /\.(jpe?g|png|webp|gif|avif)(\?|$)/i.test(url);

const decodeUrl = (url) => String(url).replace(/&#0?38;|&amp;/g, '&');

function feedImage(item) {
	const enclosure = item.enclosure;
	if (enclosure?.url && (/^image\//.test(enclosure.type || '') || looksLikeImage(enclosure.url))) {
		return decodeUrl(enclosure.url);
	}
	const media = firstUrl(item['media:content']) || firstUrl(item['media:thumbnail']);
	if (media) return decodeUrl(media);
	const html = `${item['content:encoded'] || ''} ${item.content || ''}`;
	const img = html.match(/<img[^>]+src=["']([^"']+)["']/i);
	return img ? decodeUrl(img[1]) : '';
}

const feedForLink = (link) => {
	const linkHost = host(link);
	if (!linkHost) return undefined;
	return feeds.find((feed) => {
		const feedHost = host(feed.url);
		if (!feedHost) return false;
		return (
			linkHost === feedHost || linkHost.endsWith(`.${feedHost}`) || feedHost.endsWith(`.${linkHost}`)
		);
	});
};

const now = Date.now();
const stories = [];
const keysInThisRun = new Set();

for (const { json: item } of $('Read news feeds').all()) {
	if (item.error || !item.title || !item.link) continue;

	const published = new Date(item.isoDate || item.pubDate || 0).getTime();
	if (!published || now - published > maxAgeMs || published > now + 60 * 60 * 1000) continue;

	const feed = feedForLink(item.link);
	const categories = Array.isArray(item.categories) ? item.categories.join(' ') : '';
	const text = `${item.title} ${categories} ${item.contentSnippet || ''} ${item.link}`;
	const hasUfc =
		feed?.allUfc ||
		/(^|[^a-z])ufc([^a-z]|$)/i.test(text) ||
		/\bultimate fighting championship\b/i.test(text) ||
		/\bufc\s*\d{2,4}\b/i.test(text);
	if (!hasUfc) continue;

	const nonUfcSport =
		/\b(wrestling|real american freestyle|\braf\b|wwe|bare knuckle|nhra|nba\b|nfl\b|mlb\b|ncaa wrestling)\b/i.test(
			text,
		);
	if (!feed?.allUfc && nonUfcSport && !/(^|[^a-z])ufc([^a-z]|$)/i.test(text)) continue;

	const keys = [linkKey(item.link), titleKey(item.title)];
	if (keys.some((key) => seen.has(key) || keysInThisRun.has(key))) continue;
	keys.forEach((key) => keysInThisRun.add(key));

	stories.push({
		title: String(item.title).trim(),
		link: item.link,
		source: feed?.name || host(item.link),
		publishedAt: new Date(published).toISOString(),
		snippet: String(item.contentSnippet || item.content || '').slice(0, 2000),
		feedImage: feedImage(item),
		keys,
	});
}

stories.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));

// Take the newest story of each outlet in turn, so one busy feed does not fill every slot.
const bySource = new Map();
for (const story of stories) {
	if (!bySource.has(story.source)) bySource.set(story.source, []);
	bySource.get(story.source).push(story);
}
const queues = [...bySource.values()];
const mixed = [];
while (mixed.length < candidateCount && queues.some((queue) => queue.length > 0)) {
	for (const queue of queues) {
		const next = queue.shift();
		if (next) mixed.push(next);
		if (mixed.length >= candidateCount) break;
	}
}

return mixed.map((story) => ({ json: story }));

// Turn each picked story into a post draft: clean article facts, image links, and a backup caption.
// The AI caption is written later for each story that gets exported.
const settings = $('Settings').first().json;
const stories = $('Pick new UFC stories').all();
const pages = $input.all();

const NAMED_ENTITIES = {
	amp: '&',
	quot: '"',
	apos: "'",
	nbsp: ' ',
	lt: '<',
	gt: '>',
	lsquo: '‘',
	rsquo: '’',
	ldquo: '“',
	rdquo: '”',
	hellip: '…',
	ndash: '–',
	mdash: '—',
};

const codePoint = (value) =>
	value > 0 && value <= 0x10ffff ? String.fromCodePoint(value) : '';

const decode = (text) =>
	String(text ?? '')
		.replace(/&#x([0-9a-f]+);/gi, (_, hex) => codePoint(parseInt(hex, 16)))
		.replace(/&#(\d+);/g, (_, dec) => codePoint(Number(dec)))
		.replace(/&([a-z]+);/gi, (entity, name) => NAMED_ENTITIES[name.toLowerCase()] ?? entity);

function metaContent(html, names) {
	if (typeof html !== 'string') return '';
	for (const tag of html.match(/<meta\b[^>]*>/gi) || []) {
		const name = tag.match(/(?:property|name)\s*=\s*["']([^"']+)["']/i)?.[1]?.toLowerCase();
		if (!names.includes(name)) continue;
		const content = tag.match(/content\s*=\s*"([^"]*)"|content\s*=\s*'([^']*)'/i);
		const value = content?.[1] ?? content?.[2];
		if (value) return decode(value).trim();
	}
	return '';
}

function pageImage(html) {
	const url = metaContent(html, ['og:image', 'og:image:secure_url', 'twitter:image', 'twitter:image:src']);
	return /^https?:\/\//i.test(url) ? url : '';
}

const pageSummary = (html) => metaContent(html, ['og:description', 'description', 'twitter:description']);

const stripTags = (html) =>
	String(html ?? '')
		.replace(/<(script|style|noscript|figure|figcaption|iframe|svg|form|button)\b[\s\S]*?<\/\1>/gi, ' ')
		.replace(/<[^>]+>/g, ' ');

function cleanText(text) {
	return decode(stripTags(text))
		.replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, ' ')
		.replace(/The post .* appeared first on .*$/is, '')
		.replace(/Read the Full Article Here/gi, ' ')
		.replace(/\bAdvertisement\b/g, ' ')
		.replace(/\s*\[(?:…|\.\.\.)\]\s*$/, '…')
		.replace(/\s+([,.;:!?])/g, '$1')
		.replace(/\s+/g, ' ')
		.trim();
}

const PAGE_CHROME =
	/(cookie|privacy policy|terms of (use|service)|newsletter|subscribe|sign up|sign in|log in|follow (us|me|him|her)\b|all rights reserved|©|click here|download the app|getty images|photo (by|credit)|image credit|read more|related:|share this|leave a comment|join the conversation|affiliate|sportsbook|promo code|odds (via|by))/i;

const SOCIAL_EMBED =
	/<blockquote\b[^>]*class\s*=\s*["'][^"']*(twitter|instagram|tiktok|bluesky)[^"']*["'][\s\S]*?<\/blockquote>/gi;

// Split the article into text blocks. Some sites use <p>, others use <br> between paragraphs.
function articleBlocks(html) {
	if (typeof html !== 'string') return [];
	const scope =
		html.match(/<article\b[\s\S]*?<\/article>/i)?.[0] || html.match(/<main\b[\s\S]*?<\/main>/i)?.[0] || html;
	return scope
		.replace(/\s+/g, ' ')
		.replace(/<(script|style|noscript|figure|figcaption|iframe|svg|form|button|nav|aside|footer)\b[\s\S]*?<\/\1>/gi, '\n')
		.replace(SOCIAL_EMBED, '\n')
		.replace(/<br\s*\/?>|<\/(p|div|li|h[1-6]|blockquote|section|tr)>/gi, '\n')
		.split('\n')
		.map(cleanText)
		.filter((block) => block.length >= 60 && !PAGE_CHROME.test(block));
}

const ABBREVIATION = /\b(vs|jr|sr|mr|mrs|ms|dr|st|no|u\.s|u\.k|jan|feb|mar|apr|jun|jul|aug|sep|sept|oct|nov|dec)\.$/i;

function sentences(text) {
	const pieces = String(text)
		.split(/(?<=[.!?…]["'”’)]?)\s+(?=["'“‘(]?[A-Z0-9])/)
		.map((piece) => piece.trim())
		.filter(Boolean);
	const out = [];
	for (const piece of pieces) {
		const last = out[out.length - 1];
		if (last && ABBREVIATION.test(last)) out[out.length - 1] = `${last} ${piece}`;
		else out.push(piece);
	}
	return out;
}

const fingerprint = (text) =>
	String(text)
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, ' ')
		.trim();

// A whole sentence ends with a full stop, a question mark, or an exclamation mark.
// Subheadings and summaries that a site cut short do not.
const isWhole = (sentence) => /[.!?]["'”’)\]]*$/.test(sentence) && !/(…|\.\.\.)["'”’)\]]*$/.test(sentence);

// Collect unique, whole sentences about the story, best source first.
function storyFacts(story, html) {
	const title = decode(story.title).trim();
	const titlePrint = fingerprint(title);
	const seen = new Set([titlePrint]);
	const facts = [];

	const add = (text, { anySentence = false } = {}) => {
		const withoutTitle = title ? String(text).split(title).join(' ') : String(text);
		for (const sentence of sentences(cleanText(withoutTitle))) {
			const print = fingerprint(sentence);
			if (print.length < 25 || seen.has(print) || titlePrint.includes(print)) continue;
			if (!anySentence && !isWhole(sentence)) continue;
			if (PAGE_CHROME.test(sentence)) continue;
			seen.add(print);
			facts.push(sentence);
		}
	};

	add(pageSummary(html));
	for (const block of articleBlocks(html)) add(block);
	if (facts.join(' ').length < 240) add(story.snippet);
	if (facts.length === 0) add(pageSummary(html) || story.snippet, { anySentence: true });
	return facts;
}

// Join whole sentences until the limit; never stop in the middle of a word.
function joinUpTo(parts, max) {
	let text = '';
	for (const part of parts) {
		const next = text ? `${text} ${part}` : part;
		if (next.length > max) break;
		text = next;
	}
	if (text || parts.length === 0) return text;
	const cut = parts[0].slice(0, max);
	return `${cut.slice(0, Math.max(cut.lastIndexOf(' '), max - 30)).trim()}…`;
}

function backupCaption(title, facts) {
	const detail = joinUpTo(facts, 420);
	return detail ? `${title}\n\n${detail}` : title;
}

const proxied = (source, params) =>
	`https://images.weserv.nl/?url=${encodeURIComponent(source)}&${params}`;

function instagramImage(source) {
	const url = proxied(source, 'w=1080&h=1080&fit=contain&cbg=000000&output=jpg&q=90');
	const localLogo = String(settings.logoFilePath || '').trim();
	if (localLogo) return url;
	const logo = String(settings.logoPublicUrl || '').trim();
	if (!logo || logo.includes('PASTE_PUBLIC')) return url;
	const scale = Number(settings.logoMarkScale || 14);
	const pad = Number(settings.logoMarkPad || 22);
	return `${url}&mark=${encodeURIComponent(logo)}&markpos=bottom-right&markpad=${pad}&markscale=${scale}`;
}

const width = Math.round(Number(settings.imageWidth) || 1080);
const height = Math.round(Number(settings.imageHeight) || 1920);
const tags = String(settings.hashtags || '#ufc #mma #ufcnews #mixedmartialarts #fightnews')
	.toLowerCase()
	.split(/\s+/)
	.filter(Boolean)
	.slice(0, 5)
	.join(' ');

const posts = [];
for (let i = 0; i < stories.length; i++) {
	const story = stories[i].json;
	const html = pages[i]?.json?.data;
	const sourceImage = pageImage(html) || story.feedImage;
	if (!sourceImage) continue;

	const title = decode(story.title).replace(/\s+/g, ' ').trim();
	const facts = storyFacts(story, html);
	const captionBody = backupCaption(title, facts);

	posts.push({
		json: {
			...story,
			title,
			sourceImage,
			imageUrl: instagramImage(sourceImage),
			// Sharp photo at full width, and a blurred copy that fills the whole frame behind it.
			photoUrl: proxied(sourceImage, `w=${width}&output=png`),
			backdropUrl: proxied(sourceImage, `w=${width}&h=${height}&fit=cover&blur=35&output=jpg&q=75`),
			storyFacts: joinUpTo(facts, 1800),
			captionBody,
			caption: `${captionBody}\n\nSource: ${story.source}\n\n${tags}`,
			captionSource: 'backup',
		},
	});
}

return posts;

// Pick up to N newest stories whose image is a valid JPEG (N from Settings → exportsPerRun).
const settings = $('Settings').first().json;
const limit = Math.max(1, Math.min(10, Number(settings.exportsPerRun) || 5));

const posts = $('Build Instagram posts').all();
const checks = $('Check images').all();

const working = posts.filter((post, i) => {
	const check = checks[i]?.json ?? {};
	const type = String(check.headers?.['content-type'] ?? '');
	return check.statusCode === 200 && type.startsWith('image/jpeg');
});

return working.slice(0, limit).map((post) => ({ json: post.json }));

// One opaque folder per post with neutral filenames (needs fs — start n8n with pnpm dev:up).
// This node runs once for each story, so each story gets its own folder.
const fs = require('fs');

const post = $json;
const settings = $('Settings').first().json;
let folder = String(settings.downloadsFolder || '').trim();
if (!folder) folder = '/Users/figueroaf/.n8n-files';
if (folder.startsWith('~/')) {
	throw new Error(
		'Set a full path in Settings → downloadsFolder (example: /Users/you/Downloads). Tilde (~) is not supported.',
	);
}
folder = folder.replace(/\/$/, '');

const id = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 11)}`;
const postDir = `${folder}/${id}`;
fs.mkdirSync(postDir, { recursive: true });

return {
	json: {
		...post,
		downloadsFolder: folder,
		exportDir: postDir,
		exportId: id,
		fileBase: postDir,
		imagePath: `${postDir}/cover.jpg`,
		captionPath: `${postDir}/note.txt`,
		metaPath: `${postDir}/data.json`,
	},
};

// Build the Ollama request for one exported story. This node runs once for each story.
const settings = $('Settings').first().json;
const post = $json;
const headline = String(post.captionHeadline ?? post.title ?? '').trim();
const articleText = String(post.captionFacts ?? post.storyFacts ?? post.title ?? '').trim();

const system = `You write Instagram captions for a UFC news page. Fight fans read them on their phones.

Write like a fan who knows the sport: direct, clear, and natural. Use only the facts in the article text. Never add records, dates, quotes, results, or opinions that are not in the article text. If the article text is thin, write less.

Answer with JSON that has these fields:
- "hook": one sentence of 8 to 16 words that says what happened. Use your own words. It is not a question and it is not clickbait.
- "body": 2 or 3 sentences, 40 to 70 words in total. Give the key details and what comes next. Do not repeat the hook.
- "question": one short question that asks fans what they think about this story.
- "fighters": the full names of the fighters in the headline, 3 at most.

Rules for the text: no hashtags, no emojis, no links, no outlet or author names, no dates of publication. Do not start with "In a", "Breaking", or "It's official". Use contractions.`;

const user = `Headline: ${headline}

Article text:
${articleText}`;

const ollamaRequest = {
	model: String(settings.ollamaModel || 'llama3.2'),
	stream: false,
	messages: [
		{ role: 'system', content: system },
		{ role: 'user', content: user },
	],
	// A JSON schema keeps a small local model from adding a preamble or markdown.
	format: {
		type: 'object',
		properties: {
			hook: { type: 'string' },
			body: { type: 'string' },
			question: { type: 'string' },
			fighters: { type: 'array', items: { type: 'string' } },
		},
		required: ['hook', 'body', 'question', 'fighters'],
	},
	// A low temperature keeps the text close to the article.
	options: { temperature: 0.3, top_p: 0.9, num_predict: 400, num_ctx: 4096 },
};

return { json: { ...post, ollamaRequest } };

// Clean the Ollama answer and assemble the caption. Use the backup caption when Ollama gave nothing usable.
const settings = $('Settings').first().json;
const { ollamaRequest, ...post } = $('Build caption prompt').item.json;
const reply = $input.item.json ?? {};

const headline = String(post.captionHeadline ?? post.title ?? '').trim();
const articleText = String(post.captionFacts ?? post.storyFacts ?? '').trim();
const outlet = String(post.captionSource ?? post.source ?? 'UFC News').trim();
const storyLink = String(post.captionLink ?? post.link ?? '').trim();

const tidy = (value) =>
	String(value ?? '')
		.replace(/https?:\/\/\S+/g, ' ')
		.replace(/#[\p{L}\p{N}_]+/gu, ' ')
		.replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, ' ')
		.replace(/[*_`]+/g, '')
		.replace(/\s+([,.;:!?])/g, '$1')
		.replace(/\s+/g, ' ')
		.trim()
		.replace(/^["“”']+|["“”']+$/g, '')
		.trim();

const plain = (text) =>
	String(text)
		.normalize('NFD')
		.replace(/[\u0300-\u036f]/g, '')
		.toLowerCase();

// A small local model sometimes adds claims that the article does not make. Keep a sentence only
// when most of its words, and all of its numbers and names, come from the article.
const article = plain(`${headline} ${articleText}`);
const COMMON_WORDS = new Set(
	`about after again also always been before being both could does doing down each even ever every
	fans from have having here into just know like make many more most much must need next only other
	over really said same says should some still such sure take than that their them then there these
	they thing think this those very want what when where which while will with would your`.split(/\s+/),
);
const stems = (text) =>
	(plain(text).match(/[a-z0-9]+/g) ?? [])
		.filter((word) => word.length > 3 && !COMMON_WORDS.has(word))
		.map((word) => word.slice(0, 5));
const articleStems = new Set(stems(article));

function fromArticle(sentence, minShare) {
	const numbers = sentence.match(/\d[\d,.:-]*\d|\d/g) ?? [];
	if (numbers.some((number) => !article.includes(number))) return false;
	// A capital letter after the first word marks a name.
	const names = sentence.split(/\s+/).slice(1).filter((word) => /^[A-Z][a-z]{2,}/.test(word));
	if (names.some((name) => !article.includes(plain(name.replace(/[^\p{L}].*$/u, ''))))) return false;
	const words = stems(sentence);
	if (words.length === 0) return true;
	return words.filter((word) => articleStems.has(word)).length / words.length >= minShare;
}

const splitSentences = (text) => text.split(/(?<=[.!?]["”’)]?)\s+/).filter(Boolean);

function readAnswer() {
	if (reply.error) {
		const detail = typeof reply.error === 'string' ? reply.error : reply.error.message;
		throw new Error(detail || 'Ollama request failed');
	}
	const content = reply.message?.content ?? reply.response;
	if (!content) throw new Error('Ollama returned no text');
	const answer = typeof content === 'string' ? JSON.parse(content) : content;

	const hook = tidy(answer.hook);
	const question = tidy(answer.question);
	const body = splitSentences(tidy(answer.body))
		.map((sentence) => sentence.trim())
		.filter((sentence) => !sentence.endsWith('?') && fromArticle(sentence, 0.6))
		.join(' ');
	if (body.length < 80 || body.length > 900) {
		throw new Error('Ollama text did not match the article closely enough');
	}

	const hookFits = hook.length >= 15 && hook.length <= 200 && fromArticle(hook, 0.6);
	const questionFits =
		question.endsWith('?') && question.length >= 15 && question.length <= 180 && fromArticle(question, 0.4);

	return {
		hook: hookFits ? hook.replace(/([^.!?])$/, '$1.') : headline,
		body,
		question: questionFits ? question : '',
		fighters: Array.isArray(answer.fighters) ? answer.fighters : [],
	};
}

// Keep a name tag only when the article really names that person. Names in the headline come
// first. When the headline has no name, one name from the article is enough.
function nameTags(fighters) {
	const headlinePlain = plain(headline);
	const inHeadline = [];
	const inArticle = [];
	for (const fighter of fighters) {
		const name = tidy(fighter);
		const words = name.split(' ');
		if (words.length < 2 || words.length > 4 || !article.includes(plain(name))) continue;
		const tag = `#${plain(name).replace(/[^a-z0-9]/g, '')}`;
		const list = headlinePlain.includes(plain(name)) ? inHeadline : inArticle;
		if (tag.length > 3 && !list.includes(tag)) list.push(tag);
	}
	return inHeadline.length > 0 ? inHeadline.slice(0, 3) : inArticle.slice(0, 1);
}

function eventTags() {
	const tags = [];
	const numbered = headline.match(/\bUFC\s?(\d{3})\b/i);
	if (numbered) tags.push(`#ufc${numbered[1]}`);
	if (/\bUFC Fight Night\b/i.test(headline)) tags.push('#ufcfightnight');
	return tags;
}

// Closes the caption when the model gave no usable question.
const OPEN_QUESTION = 'What’s your take? Tell us in the comments.';

let parts;
let captionSource = 'ollama';
let captionError;
let extraTags = eventTags();

try {
	const answer = readAnswer();
	parts = [answer.hook, answer.body, answer.question || OPEN_QUESTION];
	extraTags = [...nameTags(answer.fighters), ...extraTags];
} catch (error) {
	// The export continues with the backup text. data.json records why.
	parts = [post.captionBody || headline, OPEN_QUESTION];
	captionSource = 'backup';
	captionError = error.message;
}

// Instagram allows at most five hashtags per post.
const MAX_HASHTAGS = 5;
const baseTags = String(settings.hashtags || '#ufc #mma #ufcnews #mixedmartialarts #fightnews')
	.toLowerCase()
	.split(/\s+/)
	.filter(Boolean);
const hashtags = [...new Set([...baseTags, ...extraTags])].slice(0, MAX_HASHTAGS).join(' ');

const credit = [`Source: ${outlet}`];
if (settings.includeLinkInCaption && storyLink) credit.push(`Full story: ${storyLink}`);

const caption = [...parts, credit.join('\n'), hashtags].join('\n\n');

return {
	json: {
		...post,
		caption,
		captionSource,
		...(captionError ? { captionError } : {}),
	},
};

// Plan where each part of the story image goes. The Edit Image nodes after this node read `layout`.
const settings = $('Settings').first().json;
const post = $('Finish caption').item.json;
const item = $input.item;

if (!item.binary?.data || !item.binary?.photo) {
	throw new Error(`Image download failed for "${post.title}". Check photoUrl and backdropUrl in data.`);
}

const W = Math.round(Number(settings.imageWidth) || 1080);
const H = Math.round(Number(settings.imageHeight) || 1920);
const u = W / 1080;
const px = (value) => Math.round(value * u);

// Impact advance widths in thousandths of the font size. Another headline font uses them as an estimate.
const GLYPH_WIDTHS = {
	168: ',‘’',
	176: ' ',
	185: "'.",
	202: ':;',
	270: '!',
	288: 'IÍ',
	294: '-',
	313: '()',
	331: 'J',
	345: '“”',
	370: '"',
	380: 'L',
	381: '1',
	392: '7',
	396: '/',
	397: 'ZŽ',
	398: 'F',
	416: 'EÈÉÊË',
	461: 'T',
	473: 'Y',
	482: 'X',
	500: '4–',
	502: '2P',
	508: 'AÀÁÂÃÄÅ',
	517: 'SŠ',
	523: 'V',
	525: '?',
	530: '3',
	533: '+',
	535: '8',
	536: '0',
	537: '5K',
	539: 'R',
	542: '69NÑ',
	546: 'OQÓÔÕÖØ',
	547: '$UÚÜ',
	551: 'G',
	552: 'B',
	553: 'D…',
	554: 'CÇĆČ',
	555: 'H',
	576: '&',
	626: '#',
	693: '%',
	717: 'M',
	814: 'W',
	1000: '—',
};
const CAP_HEIGHT = 0.797;
const glyphWidth = new Map();
for (const [width, glyphs] of Object.entries(GLYPH_WIDTHS)) {
	for (const glyph of glyphs) glyphWidth.set(glyph, Number(width));
}
const textWidth = (text, size) =>
	([...text].reduce((sum, glyph) => sum + (glyphWidth.get(glyph) ?? 560), 0) * size) / 1000;

function wrap(text, size, maxWidth) {
	const lines = [];
	let line = '';
	for (const word of text.split(' ')) {
		const next = line ? `${line} ${word}` : word;
		if (line && textWidth(next, size) > maxWidth) {
			lines.push(line);
			line = word;
		} else {
			line = next;
		}
	}
	if (line) lines.push(line);
	return lines;
}

// Narrow the lines while the line count stays the same, so the last line is not one lonely word.
function balance(text, size, maxWidth) {
	let best = wrap(text, size, maxWidth);
	for (let width = maxWidth - 12; width > maxWidth / 2; width -= 12) {
		const lines = wrap(text, size, width);
		if (lines.length !== best.length) break;
		best = lines;
	}
	return best;
}

const display = (text) =>
	String(text ?? '')
		.replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, ' ')
		.replace(/\s+/g, ' ')
		.trim()
		.toUpperCase();

const margin = px(64);
const textWidthMax = W - margin * 2;
const headlineText = display(post.title);

// Phone apps cover the top and the bottom of a tall image, so the content stays between them.
const tall = H / W > 1.6;
const safeTop = Math.round(H * (tall ? 0.13 : 0.045));
const safeBottom = Math.round(H * (tall ? 0.17 : 0.045));
const zone = H - safeTop - safeBottom;

const logoSize = Math.round((W * Number(settings.logoMarkScale || 12)) / 100);
const labelSize = px(38);
const pillHeight = px(62);
const barHeight = px(10);
const gapHeader = px(28);
const gapPhoto = px(48);
const gapPill = px(40);
const fixedHeight = logoSize + gapHeader + barHeight + gapPhoto + pillHeight + gapPill;

const sourceWidth = Number(item.json?.size?.width) || W;
const sourceHeight = Number(item.json?.size?.height) || Math.round(W * 0.5625);
const naturalHeight = Math.round((sourceHeight * W) / sourceWidth);
// A wide photo stays whole. A tall photo is cut to this height when the headline needs the room.
const photoKeep = Math.min(naturalHeight, Math.round(W * 0.62));
const photoFloor = Math.min(naturalHeight, px(400));

const MAX_LINES = 5;
let headline;
for (let size = 96; size >= 60; size -= 4) {
	const fontSize = px(size);
	const lines = wrap(headlineText, fontSize, textWidthMax);
	const leading = Math.round(fontSize * 1.14);
	const blockHeight = Math.round(fontSize * CAP_HEIGHT) + (lines.length - 1) * leading;
	const photoRoom = zone - fixedHeight - blockHeight;
	headline = { fontSize, lines, leading, blockHeight, photoRoom };
	if (lines.length <= 4 && photoRoom >= photoKeep) break;
}
if (headline.lines.length > MAX_LINES) {
	const kept = headline.lines.slice(0, MAX_LINES);
	let last = kept[MAX_LINES - 1];
	while (last.includes(' ') && textWidth(`${last}…`, headline.fontSize) > textWidthMax) {
		last = last.slice(0, last.lastIndexOf(' '));
	}
	kept[MAX_LINES - 1] = `${last}…`;
	headline.lines = kept;
	headline.blockHeight =
		Math.round(headline.fontSize * CAP_HEIGHT) + (MAX_LINES - 1) * headline.leading;
	headline.photoRoom = zone - fixedHeight - headline.blockHeight;
} else {
	headline.lines = balance(headlineText, headline.fontSize, textWidthMax);
}

const photoHeight = Math.max(photoFloor, Math.min(naturalHeight, headline.photoRoom));
const stackHeight = fixedHeight + photoHeight + headline.blockHeight;
const top = Math.max(px(40), safeTop + Math.round((zone - stackHeight) / 2));

const logoY = top;
const photoY = logoY + logoSize + gapHeader;
const barY = photoY + photoHeight;
const pillY = barY + barHeight + gapPhoto;
const headlineY = pillY + pillHeight + gapPill + Math.round(headline.fontSize * CAP_HEIGHT);

const label = display(settings.postLabel || 'UFC NEWS');
const pillPad = px(22);
const pillWidth = Math.round(textWidth(label, labelSize)) + pillPad * 2;

const layout = {
	width: W,
	height: H,
	logo: {
		size: logoSize,
		// The logo file has an empty border. Shift it so the mark lines up with the text.
		x: margin - Math.round(logoSize * 0.1),
		y: logoY,
	},
	source: {
		text: `VIA ${display(post.source)}`,
		fontSize: px(30),
		right: margin,
		y: logoY + Math.round(logoSize / 2) + px(11),
	},
	photo: {
		y: photoY,
		width: W,
		height: photoHeight,
		fullHeight: naturalHeight,
		// Cut more from the bottom than from the top, because faces are near the top.
		cropY: Math.round((naturalHeight - photoHeight) * 0.25),
	},
	bar: { y1: barY, y2: barY + barHeight },
	pill: {
		x1: margin,
		y1: pillY,
		x2: margin + pillWidth,
		y2: pillY + pillHeight,
		radius: px(8),
		text: label,
		fontSize: labelSize,
		textX: margin + pillPad,
		textY: pillY + Math.round((pillHeight + labelSize * CAP_HEIGHT) / 2),
	},
	headline: {
		fontSize: headline.fontSize,
		x: margin,
		lines: Array.from({ length: MAX_LINES }, (_, i) => headline.lines[i] ?? ''),
		y: Array.from({ length: MAX_LINES }, (_, i) => headlineY + i * headline.leading),
	},
};

return { json: { ...post, layout }, binary: item.binary };

